from playwright.sync_api import sync_playwright,expect
import json
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('dialog',lambda d:d.accept());page.goto('http://127.0.0.1:8000/prototype-vgp.html#material')
 # New fiches can use standard names without preventing legacy free names.
 for n in (1,2):
  page.locator('#add').click();f=page.locator('#equipmentForm');f.locator('[name=identifier]').fill('NOM-FICTIF-'+str(n));f.locator('[name=typeId]').select_option('__free__');f.locator('[name=designation]').fill('ancien nom fictif m16');f.get_by_role('button',name='Enregistrer l’équipement').click();expect(page.locator('#editor')).not_to_be_visible()
 page.locator('#add').click();f=page.locator('#equipmentForm');f.locator('[name=identifier]').fill('TYPE-FICTIF');f.locator('[name=typeId]').select_option('anneau-retournement');f.locator('[name=variantId]').select_option('anneau-m30');expect(page.locator('#standardNamePreview')).to_contain_text('M30');f.get_by_role('button',name='Enregistrer l’équipement').click();expect(page.locator('#editor')).not_to_be_visible();expect(page.locator('#list')).to_contain_text('Anneau de retournement · M30')
 # Create another type, and one variant; wrong variants disappear on type change.
 page.locator('#add').click();f.locator('[name=identifier]').fill('CUSTOM-FICTIF');page.locator('#addEquipmentType').click();page.locator('#catalogItemForm [name=label]').fill('Élingue fictive');page.locator('#catalogItemForm').get_by_role('button',name='Enregistrer le libellé').click();expect(page.locator('#catalogItemDialog')).not_to_be_visible();page.locator('#addEquipmentVariant').click();page.locator('#catalogItemForm [name=label]').fill('2 tonnes');page.locator('#catalogItemForm').get_by_role('button',name='Enregistrer le libellé').click();expect(page.locator('#standardNamePreview')).to_contain_text('Élingue fictive · 2 tonnes');f.get_by_role('button',name='Enregistrer l’équipement').click();expect(page.locator('#editor')).not_to_be_visible()
 before=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));old={e['id']:e for e in before['equipment']}
 page.locator('#settingsToggle').click();page.locator('#namingSettings').click();page.locator('#namingSearch').fill('ancien nom fictif');expect(page.locator('#namingGroups label')).to_have_count(1);page.locator('#namingGroups input').check();page.locator('#bulkNamingType').select_option('anneau-retournement');page.locator('#bulkNamingVariant').select_option('anneau-m16');page.locator('#previewNaming').click();expect(page.locator('#namingPreview tbody tr')).to_have_count(2);page.locator('[data-naming-include]').first.uncheck();expect(page.locator('#namingPreviewCount')).to_contain_text('1 fiche(s)');page.locator('[data-naming-include]').first.check();expect(page.locator('#namingPreviewCount')).to_contain_text('2 fiche(s)');page.locator('#applyNaming').click();expect(page.locator('#namingStatus')).to_contain_text('2 fiche(s) standardisée(s)');expect(page.locator('#namingGroups')).to_contain_text('Aucun nom à standardiser')
 data=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));classified=[e for e in data['equipment'] if e['identifier'].startswith('NOM-FICTIF')];assert len(classified)==2
 for e in classified:assert e['designation']=='Anneau de retournement · M16' and e['originalDesignation']=='ancien nom fictif m16' and e['standardName']=='Anneau de retournement · M16' and e['controls']==old[e['id']]['controls'] and e['obligations']==old[e['id']]['obligations'] and e['namingHistory'][-1]['originalName']==e['originalDesignation']
 page.locator('#namingDialog [data-close]').click();page.locator('#search').fill('ancien nom fictif');expect(page.locator('#list tbody tr')).to_have_count(2);page.locator('#search').fill('Anneau de retournement');expect(page.locator('#list tbody tr')).to_have_count(5);page.locator('#list tbody tr').filter(has_text='NOM-FICTIF-1').get_by_role('button',name='Ouvrir',exact=True).click();expect(page.locator('#detailContent')).to_contain_text('Nom d’origine conservé : ancien nom fictif m16');page.locator('#newControl').click();control=page.locator('#controlForm');control.locator('[name=intervenant]').fill('Vérificateur fictif');control.locator('[name=result]').select_option('Bon état');control.get_by_role('button',name='Enregistrer le contrôle',exact=True).click();expect(page.locator('#control')).not_to_be_visible();saved=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));record=next(e for e in saved['equipment'] if e['identifier']=='NOM-FICTIF-1');assert record['controls'][0]['equipmentSnapshot']['designation']=='Anneau de retournement · M16' and record['controls'][0]['equipmentSnapshot']['originalDesignation']=='ancien nom fictif m16';page.locator('#detail [data-close]').click();page.reload();expect(page.locator('#list')).to_contain_text('Anneau de retournement · M16');assert page.evaluate('document.documentElement.scrollWidth')==390;assert not errors,errors;b.close()
 print('PASS : noms libres conservés, types et variantes créés, deux fiches standardisées après aperçu, recherche par ancien et nouveau nom, historique, persistance et mobile.')
